const M = {};
M.config = (function () {
  const module = { exports: {} };
/**
 * config.js – builds the runtime config for every workflow from environment variables.
 * Used by the first "Config" Code node in each workflow. Secrets are NOT copied into
 * the output (execution data is stored in n8n); HTTP nodes read tokens from $env directly.
 */
function bool(v, dflt) {
  if (v === undefined || v === null || v === '') return dflt;
  return String(v).trim().toLowerCase() === 'true';
}

function parseList(v) {
  return String(v || '')
    .split(/[,;\s]+/)
    .map((s) => s.trim().toLowerCase())
    .filter(Boolean);
}

function parseLimit(v, demoMode) {
  if (v === undefined || v === null || v === '') return demoMode ? 10 : null;
  if (String(v).trim().toLowerCase() === 'off') return null;
  const n = parseInt(v, 10);
  return Number.isFinite(n) && n > 0 ? n : 10;
}

function trimSlash(u) {
  return String(u || '').replace(/\/+$/, '');
}

function buildConfig(env) {
  env = env || {};
  // Safe defaults: demo mode ON unless explicitly "false".
  const demoMode = bool(env.DEMO_MODE, true);
  const mock = bool(env.MOCK_EXTERNAL, false);
  const mockBase = trimSlash(env.MOCK_BASE_URL || 'http://host.docker.internal:8787');
  const real = {
    airtable: 'https://api.airtable.com/v0',
    googlePlaces: 'https://places.googleapis.com/v1',
    openai: 'https://api.openai.com/v1',
    anthropic: 'https://api.anthropic.com/v1',
    slack: 'https://slack.com/api',
    gmail: 'https://gmail.googleapis.com/gmail/v1',
    hubspot: 'https://api.hubapi.com',
    dns: 'https://dns.google',
    web: '',
    calendly: 'https://api.calendly.com',
  };
  const mocked = {
    airtable: mockBase + '/airtable/v0',
    googlePlaces: mockBase + '/google/v1',
    openai: mockBase + '/ai/openai/v1',
    anthropic: mockBase + '/ai/anthropic/v1',
    slack: mockBase + '/slack/api',
    gmail: mockBase + '/gmail/v1',
    hubspot: mockBase + '/hubspot',
    dns: mockBase + '/dns',
    web: mockBase + '/web',
    calendly: mockBase + '/calendly',
  };
  const urls = mock ? mocked : real;
  const aiProvider = String(env.AI_PROVIDER || 'openai').toLowerCase() === 'anthropic' ? 'anthropic' : 'openai';
  const allowlist = parseList(env.TEST_RECIPIENT_ALLOWLIST);
  const conf = parseFloat(env.AUTO_REPLY_MIN_CONFIDENCE);
  return {
    demoMode,
    mock,
    allowRealSending: !demoMode && bool(env.ALLOW_REAL_SENDING, false),
    // DEMO_MODE sends from an every-minute ticker; the test stack turns it off and drives sends by webhook
    demoTicker: !bool(env.DISABLE_DEMO_TICKER, false),
    // cap per run so one run always finishes before the next tick (no overlapping runs)
    maxSendsPerRun: demoMode ? 6 : 5,
    testLeadLimit: parseLimit(env.TEST_LEAD_LIMIT, demoMode),
    allowlist,
    testProspectEmail: String(env.TEST_PROSPECT_EMAIL || '').trim().toLowerCase(),
    senderEmail: String(env.SENDER_EMAIL || '').trim().toLowerCase(),
    autoReplyMinConfidence: Number.isFinite(conf) ? conf : 0.85,
    unsureConfidence: 0.7,
    timezone: 'Europe/Berlin',
    airtableBaseId: env.AIRTABLE_BASE_ID || '',
    airtableUrl: urls.airtable + '/' + (env.AIRTABLE_BASE_ID || ''),
    googlePlacesUrl: urls.googlePlaces,
    aiProvider,
    aiModel: env.AI_MODEL || (aiProvider === 'anthropic' ? 'claude-haiku-5-5' : 'gpt-4o-mini'),
    aiUrl: aiProvider === 'anthropic' ? urls.anthropic + '/messages' : urls.openai + '/chat/completions',
    slackApiUrl: urls.slack,
    slackChannel: env.SLACK_CHANNEL || '#leads',
    gmailUrl: urls.gmail,
    hubspotUrl: urls.hubspot,
    dnsUrl: urls.dns,
    webProxyUrl: urls.web,
    calendlyLink: env.CALENDLY_LINK || '',
    calendlyApiUrl: urls.calendly,
    n8nBaseUrl: trimSlash(env.WEBHOOK_URL || 'http://localhost:5678'),
    n8nInternalUrl: trimSlash(env.N8N_INTERNAL_URL || 'http://localhost:5678'),
    interfaceUrl: env.AIRTABLE_INTERFACE_URL || (env.AIRTABLE_BASE_ID ? 'https://airtable.com/' + env.AIRTABLE_BASE_ID : ''),
    googleCostPerRequestEur: 0.032,
  };
}

/** URL to fetch a company web page; in mock mode served by the mock server. */
function webUrl(cfg, domain, path) {
  path = path || '/';
  if (cfg.webProxyUrl) return cfg.webProxyUrl + '/' + domain + path;
  return 'https://' + domain + path;
}

const configApi = { buildConfig, webUrl, parseList, parseLimit };
if (typeof module !== 'undefined' && module.exports) module.exports = configApi;

  return module.exports;
})();

// ---- node logic ----
const trigger = $input.all().map((i) => i.json);
// test stack only: schedules are switched off so tests drive every module through its webhook
const scheduled = trigger.length > 0 && trigger[0] && trigger[0]['Readable date'] !== undefined;
if (scheduled && String($env.DISABLE_SCHEDULES).toLowerCase() === 'true') return [];
return [{ json: { cfg: M.config.buildConfig($env), trigger, startedAt: new Date().toISOString() } }];

const M = {};
M.replies = (function () {
  const module = { exports: {} };
/**
 * replies.js – Module 7 reply handling: normalise, match to a lead, detect bounces,
 * cheap rule-based pre-classification (STOP, auto-replies) and branch routing.
 */
function addr(v) {
  if (!v) return '';
  if (typeof v === 'object') {
    if (Array.isArray(v.value) && v.value[0]) return String(v.value[0].address || '').toLowerCase();
    if (v.address) return String(v.address).toLowerCase();
    if (v.text) return addr(v.text);
  }
  const m = String(v).match(/<([^>]+)>/);
  return String(m ? m[1] : v).trim().toLowerCase();
}

function stripQuoted(text) {
  const lines = String(text || '').split(/\r?\n/);
  const out = [];
  for (const l of lines) {
    if (/^\s*>/.test(l)) break;
    if (/^\s*(Am|On)\s.+(schrieb|wrote)/i.test(l)) break;
    if (/^-{2,}\s*(Original|Ursprüngliche)/i.test(l)) break;
    out.push(l);
  }
  return out.join('\n').trim();
}

/** Newsletters / notifications: list headers, bulk precedence or a typical robot sender. */
function isBulk(msg, headers) {
  const lc = {};
  Object.keys(headers || {}).forEach((k) => (lc[k.toLowerCase()] = headers[k])); // header names are case-insensitive
  const h = (k) => String(lc[k] || '').toLowerCase();
  if (msg && msg.bulk === true) return true;
  if (h('list-unsubscribe') || h('list-id')) return true;
  if (/^(bulk|list|junk)$/.test(h('precedence'))) return true;
  const from = addr((msg && msg.from) || h('from'));
  return /^(no-?reply|do-?not-?reply|newsletter|news|notifications?|notify|onboarding|marketing|mailer|updates|info-noreply)[@.+-]/.test(from);
}

/** Accepts a Gmail Trigger message (simple:false) or the test webhook payload. */
function normaliseIncoming(msg) {
  msg = msg || {};
  const headers = msg.headers || {};
  const lc = {};
  Object.keys(headers).forEach((k) => (lc[k.toLowerCase()] = headers[k])); // header names are case-insensitive
  const h = (k) => lc[k.toLowerCase()] || '';
  const body = msg.text || msg.textPlain || msg.body || msg.snippet || '';
  return {
    message_id: msg.id || msg.message_id || '',
    thread_id: msg.threadId || msg.thread_id || '',
    from_email: addr(msg.from || h('from')),
    to_email: addr(msg.to || h('to')),
    subject: msg.subject || h('subject') || '',
    body: String(body),
    body_clean: stripQuoted(body),
    received_at: msg.date ? new Date(msg.date).toISOString() : msg.received_at || new Date().toISOString(),
    auto_submitted: String(h('auto-submitted') || msg.auto_submitted || '').toLowerCase(),
    bulk: isBulk(msg, headers),
    original_to: addr(msg.original_to || h('x-original-recipient') || ''),
  };
}

function detectBounce(r) {
  const from = String(r.from_email || '');
  const subj = String(r.subject || '');
  if (/mailer-daemon|postmaster@/i.test(from)) return true;
  if (/(Delivery Status Notification|Undeliverable|Unzustellbar|Mail delivery failed|Returned mail|Nicht zustellbar)/i.test(subj)) return true;
  return false;
}

/** Extracts the bounced address from a bounce body. */
function bouncedAddress(r) {
  const m = String(r.body || '').match(/[a-z0-9._%+-]+@[a-z0-9.-]+\.[a-z]{2,}/gi) || [];
  return (m.find((e) => !/mailer-daemon|postmaster|googlemail\.com$/i.test(e)) || '').toLowerCase();
}

const STOP_RE = /^\s*(stop|stopp|abmelden|unsubscribe|austragen)\s*[.!]?\s*$/i;
const UNSUB_RE = /(keine (weiteren )?(e-?mails|nachrichten|kontaktaufnahme)|bitte (aus (ihrem|dem) verteiler|austragen|löschen sie)|nicht mehr kontaktieren|remove me|unsubscribe|abmelden)/i;
const OOO_RE = /(abwesenheitsnotiz|out of office|nicht im büro|außer haus|im urlaub|bin bis|automatische antwort|auto(matic)?[- ]reply)/i;

/** Parses German/ISO dates like 24.11.2026, 24.11., 2026-11-24. */
function findReturnDate(text, now) {
  const t = String(text || '');
  const iso = t.match(/\b(20\d{2})-(\d{2})-(\d{2})\b/);
  if (iso) return `${iso[1]}-${iso[2]}-${iso[3]}`;
  const de = t.match(/\b(\d{1,2})\.(\d{1,2})\.(\d{2,4})?/);
  if (de) {
    const ref = new Date(now || Date.now());
    let y = de[3] ? Number(de[3].length === 2 ? '20' + de[3] : de[3]) : ref.getUTCFullYear();
    const m = Number(de[2]);
    const d = Number(de[1]);
    if (m < 1 || m > 12 || d < 1 || d > 31) return null;
    if (!de[3] && Date.UTC(y, m - 1, d) < ref.getTime() - 86400000) y += 1;
    return `${y}-${String(m).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
  }
  return null;
}

/** Deterministic pre-classification; returns null when the AI must decide. */
function ruleClassify(r, now) {
  const body = r.body_clean || r.body || '';
  if (STOP_RE.test(body) || /^\s*stop\b/i.test(body)) return { category: 'Unsubscribe', confidence: 1, return_date: null, summary: 'STOP-Antwort', by: 'rule' };
  const isAuto = /auto-replied|auto-generated/.test(r.auto_submitted || '') || OOO_RE.test(r.subject + ' ' + body.slice(0, 300));
  if (isAuto && OOO_RE.test(r.subject + ' ' + body)) {
    return { category: 'Out of office', confidence: 0.95, return_date: findReturnDate(body, now), summary: 'Abwesenheitsnotiz', by: 'rule' };
  }
  if (UNSUB_RE.test(body) && body.length < 400) return { category: 'Unsubscribe', confidence: 0.95, return_date: null, summary: 'Bittet um Austragung', by: 'rule' };
  return null;
}

/** Thread id first, then sender email. */
function matchReplyToLead(r, leads, emails) {
  leads = leads || [];
  emails = emails || [];
  if (r.thread_id) {
    const em = emails.find((e) => e.thread_id && e.thread_id === r.thread_id);
    if (em) {
      const leadId = Array.isArray(em.lead) ? em.lead[0] : em.lead || em.lead_record_id;
      const lead = leads.find((l) => l.id === leadId);
      if (lead) return { lead, by: 'thread_id' };
    }
  }
  const from = String(r.from_email || '').toLowerCase();
  const candidates = [from, r.original_to].filter(Boolean);
  const lead = leads.find((l) => candidates.includes(String(l.email || '').toLowerCase()));
  if (lead) return { lead, by: 'from_email' };
  return { lead: null, by: null };
}

/**
 * Decides the branch for a classified reply.
 * returns {branch, leadStatus, autoSend, askSlack, nextSendAt, block}
 */
function routeReply(cls, cfg, now) {
  const minAuto = (cfg && cfg.autoReplyMinConfidence) || 0.85;
  const unsure = (cfg && cfg.unsureConfidence) || 0.7;
  const t = new Date(now || Date.now());
  const conf = Number(cls.confidence) || 0;
  if (cls.category === 'Unclear' || conf < unsure) {
    return { branch: 'Unsure', leadStatus: 'Replied', askSlack: true, autoSend: false };
  }
  switch (cls.category) {
    case 'Interested':
      return { branch: 'Interested', leadStatus: 'Interested', autoSend: conf >= minAuto, askSlack: conf < minAuto };
    case 'Question':
      // answers to questions (price, process) are always approved by a person: one wrong answer can cost the client
      return { branch: 'Question', leadStatus: 'Interested', autoSend: false, askSlack: true };
    case 'Referral':
      return { branch: 'Referral', leadStatus: 'Replied' };
    case 'Later': {
      const d = cls.return_date ? new Date(cls.return_date + 'T08:00:00Z') : new Date(t.getTime() + 30 * 86400000);
      return { branch: 'Later', leadStatus: 'Later', followUpAt: d.toISOString() };
    }
    case 'Not interested':
      return { branch: 'Not interested', leadStatus: 'Not interested' };
    case 'Unsubscribe':
      return { branch: 'Unsubscribe', leadStatus: 'Unsubscribed', block: true };
    case 'Out of office': {
      const base = cls.return_date ? new Date(cls.return_date + 'T08:00:00Z') : new Date(t.getTime() + 7 * 86400000);
      const resume = new Date(base.getTime() + 86400000);
      return { branch: 'Out of office', leadStatus: 'Contacted', resumeAt: (cfg && cfg.demoMode) ? new Date(t.getTime() + 5 * 60000).toISOString() : resume.toISOString() };
    }
    default:
      return { branch: 'Unsure', leadStatus: 'Replied', askSlack: true, autoSend: false };
  }
}

/**
 * A lead says no (Not interested / Unsubscribe) after it had shown interest.
 * Plans: which booked meetings to cancel in Airtable, whether the HubSpot deal must be closed, and the Slack text.
 * Calendly itself cannot be cancelled with the read-only token, so Slack asks a person to cancel it there.
 */
function withdrawalPlan(opts) {
  const o = opts || {};
  const lead = o.lead || {};
  const name = lead.company_name || o.fromEmail || 'Lead';
  // Reminded too: a meeting that already got its 24 h reminder is still an active booking
  const booked = (o.meetings || []).filter((m) => m && (m.status === 'Booked' || m.status === 'Reminded') && (!lead.id || m.lead_record_id === lead.id));
  const wasInterested = ['Interested', 'Meeting booked', 'Meeting held'].includes(lead.status);
  const hasDeal = !!lead.hubspot_deal_id;
  const closing = o.branch === 'Not interested' || o.branch === 'Unsubscribe';
  const withdrew = closing && (wasInterested || hasDeal || booked.length > 0);
  if (!withdrew) return { withdrew: false, cancelMeetingIds: [], meetings: [], crmSync: false, text: '' };
  const head = ':leftwards_arrow_with_hook: *' + name + '* withdrew after showing interest (' + (o.branch === 'Unsubscribe' ? 'STOP, added to the Blocklist' : 'not interested') + ').';
  const meetings = booked.map((m) => ({ id: m.id, calendly_event_id: m.calendly_event_id || '', when: String(m.start_time || '').slice(0, 16).replace('T', ' ') }));
  const plan = { withdrew: true, cancelMeetingIds: booked.map((m) => m.id), meetings, crmSync: hasDeal, head, hasDeal };
  plan.text = withdrawalText(plan, null);
  return plan;
}

/**
 * Slack text after the Calendly cancellations ran. results: [{ok, problem}] in the order of plan.meetings
 * (null = not tried yet → the manual hint).
 */
function withdrawalText(plan, results) {
  const parts = [plan.head];
  if (plan.hasDeal) parts.push('HubSpot deal set to Closed lost.');
  (plan.meetings || []).forEach((m, i) => {
    const r = results && results[i];
    if (r && r.ok) parts.push('Meeting on ' + m.when + ' cancelled in Calendly automatically (the invitee got Calendly\'s cancellation email).');
    else parts.push('Meeting on ' + m.when + ' marked cancelled: *please cancel it in Calendly too*' + (r && r.problem ? ' (Calendly: ' + r.problem + ')' : '') + '.');
  });
  return parts.join(' ');
}

/**
 * "Wenden Sie sich an Frau Klein, klein@firma.de": contact the named person automatically, but only if the address is in
 * the reply, belongs to the same company (or a related domain), is not blocked and is not already a lead.
 * returns { action: 'contact' | 'task', name, email, reason }
 */
function referralPlan(o) {
  const cls = (o && o.cls) || {};
  const lead = (o && o.lead) || {};
  const body = String((o && o.replyBody) || '').toLowerCase();
  const name = String(cls.referral_name || '').trim();
  const email = String(cls.referral_email || '').trim().toLowerCase();
  const task = (reason) => ({ action: 'task', name, email, reason });
  if (!email) return task('no email address in the reply');
  if (!/^[^@\s]+@[^@\s]+\.[a-z]{2,}$/.test(email) || !body.includes(email)) return task('email not found in the reply');
  const dom = email.split('@')[1];
  const related = o.relatedDomain ? o.relatedDomain(dom, lead.domain, lead.company_name) : dom === lead.domain;
  if (!related) return task('email is not on the company domain');
  if (o.isBlocked && o.isBlocked(email, o.blocklist || [])) return task('address is on the Blocklist');
  if ((o.existingEmails || []).map((x) => String(x).toLowerCase()).includes(email)) return task('already a lead');
  if (email === String(lead.email || '').toLowerCase()) return task('same address as the original contact');
  return { action: 'contact', name, email, reason: '' };
}

const repliesApi = { isBulk, normaliseIncoming, stripQuoted, detectBounce, bouncedAddress, ruleClassify, findReturnDate, matchReplyToLead, routeReply, withdrawalPlan, withdrawalText, referralPlan, addr };
if (typeof module !== 'undefined' && module.exports) module.exports = repliesApi;

  return module.exports;
})();

// ---- node logic ----
const cfg = $('Config').first().json.cfg;
const b = $('Reply webhook').first().json.body || {};
if (b.reprocess_reply_id) return [{ json: { mode: 'reprocess', reply_id: b.reprocess_reply_id, forced_category: b.forced_category, handled_by: b.handled_by || 'Slack' } }];
const r = M.replies.normaliseIncoming(b);
if (!r.from_email || (cfg.senderEmail && r.from_email === cfg.senderEmail && !M.replies.detectBounce(r))) return []; // our own sent mail
const bounce = M.replies.detectBounce(r);
return [{ json: { mode: 'new', reply: r, bounce, bounced: bounce ? M.replies.bouncedAddress(r) : '' } }];

const n = $('Normalise').first().json;
const r = $('Load reply').first().json;
const f = r.fields || {};
return [{ json: { mode: 'reprocess', reply_record_id: r.id, forced: { category: n.forced_category, confidence: 1, return_date: null, summary: 'Von ' + n.handled_by + ' in Slack sortiert', by: 'human' },
  handled_by: n.handled_by, lead_hint: f.lead_record_id,
  reply: { message_id: f.gmail_message_id || '', thread_id: f.thread_id || '', from_email: f.from_email || '', subject: f.subject || '', body: f.body || '', body_clean: f.body || '', received_at: f.received_at } } }];

const M = {};
M.airtable = (function () {
  const module = { exports: {} };
/**
 * airtable.js – helpers for the Airtable REST API: batches of 10, formula building,
 * flattening records. Free-plan friendly (CLAUDE.md: batches of 10 per call).
 */
const BATCH = 10;

function chunk(list, size) {
  const n = size || BATCH;
  const out = [];
  for (let i = 0; i < (list || []).length; i += n) out.push(list.slice(i, i + n));
  return out;
}

function clean(fields) {
  const out = {};
  Object.keys(fields || {}).forEach((k) => {
    if (fields[k] !== undefined) out[k] = fields[k];
  });
  return out;
}

/** -> [{records:[{fields}]}] one item per HTTP call */
function createBatches(fieldsList) {
  return chunk((fieldsList || []).map((f) => ({ fields: clean(f) }))).map((records) => ({ records, typecast: true }));
}

/** updates: [{id, fields}] -> [{records:[{id, fields}]}] */
function updateBatches(updates) {
  return chunk((updates || []).filter((u) => u && u.id).map((u) => ({ id: u.id, fields: clean(u.fields) }))).map((records) => ({ records, typecast: true }));
}

function esc(v) {
  return String(v).replace(/\\/g, '\\\\').replace(/'/g, "\\'");
}

function eq(field, value) {
  if (typeof value === 'number' || typeof value === 'boolean') return `{${field}}=${value === true ? 'TRUE()' : value === false ? 'FALSE()' : value}`;
  return `{${field}}='${esc(value)}'`;
}

function and(...parts) {
  const p = parts.filter(Boolean);
  return p.length === 1 ? p[0] : `AND(${p.join(',')})`;
}

function or(...parts) {
  const p = parts.filter(Boolean);
  return p.length === 1 ? p[0] : `OR(${p.join(',')})`;
}

/** Airtable record -> flat object with id */
function flat(record) {
  if (!record) return null;
  return Object.assign({ id: record.id, createdTime: record.createdTime }, record.fields || {});
}

function flatList(response) {
  return ((response && response.records) || []).map(flat);
}

/** n8n items from a (paginated) list node -> flat records */
function fromItems(items) {
  // With pagination on, n8n's HTTP node retries and then passes the error body on instead of failing.
  // A failed read must never look like an empty table (e.g. an "empty" Blocklist), so fail here.
  (items || []).forEach((i) => {
    const e = i && i.json && i.json.error;
    if (e) throw new Error('Airtable read failed after retries: ' + (typeof e === 'string' ? e : e.message || e.type || JSON.stringify(e)).slice(0, 200));
  });
  return flatList({ records: (items || []).flatMap((i) => (i && i.json && i.json.records) || []) });
}

/** OR() over ids for a text field, e.g. lead_record_id */
function inIds(field, ids) {
  const list = Array.from(new Set((ids || []).filter(Boolean)));
  if (!list.length) return "{" + field + "}='__none__'";
  return or(...list.map((id) => eq(field, id)));
}

const airtableApi = { fromItems, inIds, BATCH, chunk, createBatches, updateBatches, eq, and, or, esc, flat, flatList, clean };
if (typeof module !== 'undefined' && module.exports) module.exports = airtableApi;

  return module.exports;
})();

// ---- node logic ----
const ctx = $('Reply from record').isExecuted ? $('Reply from record').first().json : $('Normalise').first().json;
const emails = M.airtable.fromItems($('Emails in thread').all());
const ids = emails.map((e) => e.lead_record_id).concat(ctx.lead_hint ? [ctx.lead_hint] : []).filter(Boolean);
const addrs = [ctx.reply.from_email, ctx.bounced].filter(Boolean).map((a) => String(a).toLowerCase().replace(/'/g, ''));
const parts = ids.map((id) => "RECORD_ID()='" + id + "'").concat(addrs.map((a) => "LOWER({email})='" + a + "'"));
return [{ json: Object.assign({}, ctx, { thread_emails: emails, formula: parts.length ? 'OR(' + parts.join(',') + ')' : "{email}='__none__'" }) }];

const M = {};
M.replies = (function () {
  const module = { exports: {} };
/**
 * replies.js – Module 7 reply handling: normalise, match to a lead, detect bounces,
 * cheap rule-based pre-classification (STOP, auto-replies) and branch routing.
 */
function addr(v) {
  if (!v) return '';
  if (typeof v === 'object') {
    if (Array.isArray(v.value) && v.value[0]) return String(v.value[0].address || '').toLowerCase();
    if (v.address) return String(v.address).toLowerCase();
    if (v.text) return addr(v.text);
  }
  const m = String(v).match(/<([^>]+)>/);
  return String(m ? m[1] : v).trim().toLowerCase();
}

function stripQuoted(text) {
